  function act(action){if((profile.open()||panels.open()||journey.open()||hudUI.open()||community.open()||partyUI.open()||expeditions.open()))return;if(action==='map')journey.openMap();if(action==='recall')notice(world.beginRecall().message);if(action==='attack')world.attack();if(action==='ability'){const r=world.skill();notice(r.message);}if(action==='dash')dashRequested=true;if(action==='mount')notice(world.toggleMount().message);if(action==='potion'){if(world.state.consumables[world.state.potionSlot]>0)notice(world.usePotion().message);else if(!world.potion())notice('Зілля немає або здоров’я вже повне.');}if(action==='merchant'){const gate=R.PORTALS.find(p=>Math.hypot(p.x-world.state.x,p.y-world.state.y)<135);if(gate){notice(world.crossCluster(gate.id).message);return;}if(expeditions.interact())return;if(world.nearCamp()&&Math.hypot(world.state.x-R.BILLBOARD.x,world.state.y-R.BILLBOARD.y)<110){community.openBoard();return;}if(Math.hypot(world.state.x-R.MONOLITH.x,world.state.y-R.MONOLITH.y)<105){notice(world.interact().message);return;}if(world.nearCamp()){const closest=Object.entries(R.townTraders(world.state)).sort((a,b)=>Math.hypot(a[1].x-world.state.x,a[1].y-world.state.y)-Math.hypot(b[1].x-world.state.x,b[1].y-world.state.y))[0];if(closest&&R.nearby(world.state,closest[0]))panels.town(closest[0]);else notice(world.interact().message);}else notice(world.interact().message);}if(action==='inventory')panels.inventory();if(action==='mastery')panels.mastery();if(action==='market')panels.town('market');hud();}
