  document.addEventListener('keydown',event=>{if(event.target.closest('input,select,textarea')||event.ctrlKey||event.metaKey||event.altKey)return;const controls=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight','KeyQ','KeyE','KeyR','KeyI','KeyB','KeyM','KeyT','KeyH'];if(controls.includes(event.code))event.preventDefault();if((profile.open()||panels.open()||journey.open()||hudUI.open()||community.open()||partyUI.open()||expeditions.open()))return;keys.add(event.code);if(event.repeat)return;const action={KeyQ:'potion',KeyE:'merchant',KeyI:'inventory',KeyB:'mastery',KeyR:'ability',KeyM:'map',KeyT:'recall',KeyH:'mount'}[event.code];if(action)act(action);if(event.code.startsWith('Shift'))dashRequested=true;});
